// Smoke + interaction test через Chrome DevTools Protocol (без внешних зависимостей).
import { spawn } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const FILE = process.argv[2] || '/home/dp/MyProjects/disc/.tmpwork/disc-pi-9koz5rqv/run/index.html';
const PORT = 9333;

const chrome = spawn('google-chrome', [
  '--headless=new', `--remote-debugging-port=${PORT}`,
  '--no-first-run', '--no-default-browser-check', '--disable-gpu',
  '--window-size=1280,900', '--hide-scrollbars',
  'about:blank'
], { stdio: 'ignore' });

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getWsUrl() {
  for (let i = 0; i < 60; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      const list = await res.json();
      const page = list.find((t) => t.type === 'page');
      if (page) return page.webSocketDebuggerUrl;
    } catch (e) { /* not up yet */ }
    await sleep(250);
  }
  throw new Error('chrome did not start');
}

const wsUrl = await getWsUrl();
const ws = new WebSocket(wsUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let id = 0;
const pending = new Map();
const events = [];
ws.onmessage = (m) => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) {
    const { res, rej } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? rej(new Error(JSON.stringify(msg.error))) : res(msg.result);
  } else if (msg.method) {
    events.push(msg);
  }
};
const send = (method, params = {}) => new Promise((res, rej) => {
  const mid = ++id;
  pending.set(mid, { res, rej });
  ws.send(JSON.stringify({ id: mid, method, params }));
});

const evaluate = async (expr) => {
  const r = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw new Error('JS error: ' + JSON.stringify(r.exceptionDetails));
  return r.result.value;
};

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');
await send('Network.setCacheDisabled', { cacheDisabled: true });

// перехват всех сетевых запросов
const requests = [];
ws.addEventListener('message', (m) => {
  const msg = JSON.parse(m.data);
  if (msg.method === 'Network.requestWillBeSent') requests.push(msg.params.request.url);
});

await send('Page.navigate', { url: 'file://' + FILE });
await sleep(1200);

const errors = events
  .filter((e) => e.method === 'Runtime.exceptionThrown')
  .map((e) => e.params.exceptionDetails.text + ' ' + (e.params.exceptionDetails.exception?.description || ''));
const consoleErrors = events
  .filter((e) => e.method === 'Runtime.consoleAPICalled' && e.params.type === 'error')
  .map((e) => e.params.args.map((a) => a.value ?? a.description).join(' '));

// --- 1. старт экрана
const startVisible = await evaluate(`!document.getElementById('screen-start').hidden`);
const itemsInDom = await evaluate(`document.querySelectorAll('.item').length`);
const listsInDom = await evaluate(`document.querySelectorAll('.list').length`);
const dupAdjective = await evaluate(`(() => {
  const txt = [...document.querySelectorAll('.item__text')].map(e => e.textContent);
  return txt.filter((t,i) => txt.indexOf(t) !== i).length;
})()`);

// --- 2. запуск теста
await evaluate(`document.getElementById('btn-start').click()`);
await sleep(300);
const quizVisible = await evaluate(`!document.getElementById('screen-quiz').hidden`);
const stepInfo = await evaluate(`document.getElementById('step-label').textContent + ' | ' + document.querySelectorAll('.pane:not([hidden])').length`);

// --- 3. drag&drop последнего элемента первого блока в начало
const rects = await evaluate(`(() => {
  const ul = document.querySelectorAll('.list')[0];
  const lis = [...ul.children];
  const a = lis[3].getBoundingClientRect();
  const b = lis[0].getBoundingClientRect();
  return { from: { x: a.x + a.width/2, y: a.y + a.height/2 },
           to:   { x: b.x + b.width/2, y: b.y + 6 } };
})()`);

const mouse = async (type, x, y, buttons = 1) =>
  send('Input.dispatchMouseEvent', { type, x, y, button: 'left', buttons, clickCount: 1 });

await mouse('mousePressed', rects.from.x, rects.from.y);
await sleep(30);
for (let k = 1; k <= 8; k++) {
  const y = rects.from.y + (rects.to.y - rects.from.y) * (k / 8);
  await mouse('mouseMoved', rects.from.x, y);
  await sleep(20);
}
await mouse('mouseReleased', rects.to.x, rects.to.y, 0);
await sleep(250);

const orderAfterDrag = await evaluate(`[...document.querySelectorAll('.list')[0].children].map(li => li.dataset.type + ':' + li.querySelector('.item__text').textContent).join(', ')`);
const posNumbers = await evaluate(`[...document.querySelectorAll('.list')[0].children].map(li => li.querySelector('.item__pos').textContent).join('')`);

// --- 4. пройти все шаги «Далее» и завершить
for (let i = 0; i < 7; i++) {
  await evaluate(`document.getElementById('btn-next').click()`);
  await sleep(60);
}
const finishVisible = await evaluate(`!document.getElementById('btn-finish').hidden`);
const nextHidden = await evaluate(`document.getElementById('btn-next').hidden`);
const progressWidth = await evaluate(`document.getElementById('progress-bar').style.width`);

const expected = await evaluate(`(() => {
  const lists = [...document.querySelectorAll('.list')];
  const maj = [], min = [];
  lists.forEach(ul => [...ul.children].forEach((li, i) => {
    if (i === 0) maj.push(li.dataset.type);
    if (i === 3) min.push(li.dataset.type);
  }));
  const c = (arr, ch) => arr.filter(v => v === ch).length;
  const r = { d: c(maj,'d')-c(min,'d'), i: c(maj,'i')-c(min,'i'), s: c(maj,'s')-c(min,'s'), c: c(maj,'c')-c(min,'c') };
  return 'D:' + r.d + ', I:' + r.i + ', S:' + r.s + ', C:' + r.c;
})()`);

await evaluate(`document.getElementById('btn-finish').click()`);
await sleep(500);
const resultVisible = await evaluate(`!document.getElementById('screen-result').hidden`);
const scoreText = await evaluate(`document.getElementById('score-line').textContent.trim()`);
const barsCount = await evaluate(`document.querySelectorAll('.bar').length`);
const sumScores = await evaluate(`(() => {
  const t = document.getElementById('score-line').textContent;
  return (t.match(/-?\\d+/g) || []).map(Number).reduce((a,b)=>a+b,0);
})()`);

// --- 5. рестарт
await evaluate(`document.getElementById('btn-restart').click()`);
await sleep(300);
const afterRestart = await evaluate(`[...document.querySelectorAll('.list')].slice(0,1).map(ul => [...ul.children].map(li => li.dataset.type).join(''))[0]`);
const restartScreen = await evaluate(`!document.getElementById('screen-quiz').hidden && document.getElementById('screen-result').hidden`);

// --- 6. скриншоты
const shot = async (name) => {
  const r = await send('Page.captureScreenshot', { format: 'png', captureBeyondViewport: false });
  writeFileSync(name, Buffer.from(r.data, 'base64'));
};

await evaluate(`document.getElementById('screen-quiz').hidden = true; document.getElementById('screen-start').hidden = false; window.scrollTo(0,0)`);
await sleep(200);
await shot('shot-start.png');

await evaluate(`document.getElementById('btn-start').click(); window.scrollTo(0,0)`);
await sleep(300);
await shot('shot-step1.png');

await evaluate(`document.getElementById('btn-next').click(); document.getElementById('btn-next').click(); document.getElementById('btn-next').click(); document.getElementById('btn-next').click(); document.getElementById('btn-next').click(); document.getElementById('btn-next').click(); document.getElementById('btn-next').click();`);
await sleep(300);
await shot('shot-step8.png');

await evaluate(`document.getElementById('btn-finish').click()`);
await sleep(600);
await shot('shot-result.png');

// мобильный вид
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await evaluate(`document.getElementById('screen-result').hidden = true; document.getElementById('screen-quiz').hidden = false; document.getElementById('btn-next').hidden=false; document.getElementById('btn-finish').hidden=true;`);
await evaluate(`document.querySelectorAll('.pane').forEach((p,i)=>{p.hidden = i!==0}); document.getElementById('tabs').firstElementChild.click(); window.scrollTo(0,0)`);
await sleep(400);
await shot('shot-mobile.png');

const panesCount = await evaluate(`document.querySelectorAll('[data-step-pane]').length`);
const r = {
  startVisible, itemsInDom, listsInDom, dupAdjective,
  quizVisible, stepInfo,
  orderAfterDrag, posNumbers,
  finishVisible, nextHidden, progressWidth,
  expected, resultVisible, scoreText, barsCount, sumScores,
  scoreMatches: expected === scoreText.replace(/\s+/g, ' ').trim(),
  afterRestart, restartScreen, panesCount,
  errors, consoleErrors,
  externalRequests: requests.filter((u) => !u.startsWith('file://'))
};
console.log(JSON.stringify(r, null, 2));

ws.close();
chrome.kill();
process.exit(0);

