from html.parser import HTMLParser
VOID = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','circle','path','stop','use','rect','line','polyline','polygon','ellipse'}
class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.stack=[]; self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag in VOID: return
        self.stack.append((tag, self.getpos()))
    def handle_startendtag(self, tag, attrs): pass
    def handle_endtag(self, tag):
        if tag in VOID: return
        if not self.stack: self.errors.append(('extra close', tag, self.getpos())); return
        t,pos = self.stack.pop()
        if t != tag:
            self.errors.append(('mismatch', t, tag, pos, self.getpos()))
            # resync
            while self.stack and self.stack[-1][0] != tag: self.stack.pop()
            if self.stack: self.stack.pop()
p = P()
